    seeds=[(r,c,gi[r][c]) for r in range(h) for c in range(w) if gi[r][c] not in (bgn,lane)]
    cols={col for _,_,col in seeds}
    comp=set(); q=deque()
    for sr,sc,_ in seeds:
        comp.add((sr,sc)); q.append((sr,sc))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and (nr,nc) not in comp and gi[nr][nc]!=bgn:
                comp.add((nr,nc)); q.append((nr,nc))
    out=[row[:] for row in gi]
    for (r,c) in comp:
        if gi[r][c]!=lane: continue
        d=min(abs(sr-r)+abs(sc-c) for sr,sc,_ in seeds)
        near=min(seeds,key=lambda s:(abs(s[0]-r)+abs(s[1]-c)))[2]
        tgt=near if d%2==0 else [col for col in cols if col!=near][0]
        out[r][c]=tgt
    return out
